/**
 * Hand-picked, individually verified GetYourGuide products — the network's
 * "direct sales items". Each row deep-links to ONE bookable activity page, so
 * the visitor lands on a Check-availability button instead of a search listing.
 *
 * ── Where these come from ──────────────────────────────────────────────────
 * Selected out of `shared/gyg/catalog.md` (839 products, generated by
 * `scripts/gyg-catalog.mjs`) and then opened one by one in a real browser on
 * 2026-07-29. Every row below returned HTTP 200, did NOT redirect, carried the
 * title stated here, and rendered a booking CTA.
 *
 * 🔴 NEVER add a row by guessing or hand-editing a path. A wrong id does not
 * 404 — it silently serves a real page somewhere else in the world. Measured on
 * 2026-07-29: `rovaniemi-l1155` renders Eisenstadt (Austria), `lapland-l4404`
 * renders Parc des Princes (Paris), and a guessed Korouoma id redirected to
 * Angra do Heroísmo (Azores). All three answered 200 with a valid-looking page.
 * Take the path from the catalogue, then open it before shipping.
 *
 * ── Price: shown, but always dated and attributed ─────────────────────────
 * `price` is GetYourGuide's own "from" price as it stood on GYG_PRICE_AS_OF —
 * it is NOT our price and must never be rendered as one. Every card prints the
 * source and the date next to it, so a visitor who finds a different number at
 * checkout can see why.
 *
 * Currency is EUROS. An earlier comment here claimed USD; that was wrong. All
 * 839 catalogue values begin with `€` — the USD figure lives in a product
 * page's JSON-LD (`priceCurrency: "USD"`), a different field from the visible
 * token the crawler stores. Counted 2026-07-30.
 *
 * Still deliberately absent: ratings and review counts. We have no way to keep
 * those current, and a stale "4.6 (869)" is a claim about other people's
 * experience rather than a fact about the product.
 *
 * ── Re-verification ───────────────────────────────────────────────────────
 * Activities get delisted. `lv-link-affiliate-audit-weekly` is the natural
 * place to re-check these paths; a dead row is a broken promise, not a warning.
 *
 * ── 🔴 Rivin poisto/uudelleennimeäminen rikkoo laplandgiftsin buildin ──────
 * laplandgifts/src/data/experiences.ts poimii rivejä näistä listoista
 * OTSIKKOFRAGMENTILLA (pick()-apuri, kaatuu keräysvaiheessa jos fragmentti
 * ei osu). Todistettu 2026-08-03: t505204:n poisto ACTIVITIES_PICKSistä
 * kaatoi giftsin buildin (korjattu giftsissä 98b3637). Ennen kuin poistat
 * tai uudelleennimeät rivin, greppaa otsikko myös laplandgiftsistä.
 */

export interface GygPick {
  /** GetYourGuide path: `<location-lNNN>/<slug-tNNN>`. No leading/trailing slash. */
  path: string;
  /** Title as GetYourGuide renders it, minus the "City: " prefix. */
  title: string;
  /** Destination shown to the visitor. */
  place: string;
  /**
   * GetYourGuide's "from" price on GYG_PRICE_AS_OF, euros, e.g. "188 €".
   * Optional: a row with no price in the catalogue renders without one rather
   * than with a guess. Never print this without the source and date beside it.
   */
  price?: string;
  /** Omitted when the source value was unreliable — never print a guess. */
  duration?: string;
  /**
   * Per-row override for the price's "as of" date. Set when a single row's
   * price was read on a DIFFERENT day than the catalogue crawl — the row then
   * renders its own date instead of GYG_PRICE_AS_OF, so neither date lies
   * about the other rows. (First use: christmas t434430, read 2026-08-01.)
   */
  priceAsOf?: string;
  /** Placement tag, snake_case, no domain. The Worker prefixes the site. */
  sid: string;
}

/**
 * The date the prices below were read off GetYourGuide. Rendered next to every
 * price, because an undated partner price is a promise we cannot keep — they
 * change it, not us. Re-run scripts/gyg-add-prices.mjs after a fresh crawl.
 */
export const GYG_PRICE_AS_OF = "2026-07-29";

const GO = "https://go.laplandvibes.com/go/activities";

/**
 * Affiliate href through the redirect Worker (LV rule: never a raw partner URL
 * in source). The Worker appends `partner_id` and resolves per-site attribution
 * from the Referer header. Verified end-to-end 2026-07-29.
 *
 * `lang` is handed to the WORKER as `language`. It is not passed through to
 * GetYourGuide — 🔴 `?language=xx` does nothing there, measured in a real
 * browser 2026-08-02: the product page renders identical English with and
 * without it. GetYourGuide localises by a `<lang>-<country>/` path prefix, and
 * resolves the product from its `-tNNNNN` id, so `handleGyg` turns this
 * parameter into that prefix.
 *
 * 🔴 Until 2026-08-02 the Worker's PASSTHROUGH list did not include `language`
 * at all, so this parameter was dropped on the floor and every site using
 * these picks sent its readers to the English page. Both halves of that bug
 * were invisible: the site looked like it was asking for a language, and the
 * parameter it asked with would not have worked anyway.
 */
export function gygHref(pick: GygPick, lang?: string, sidOverride?: string): string {
  // sidOverride: a pick's baked-in sid is named after the site the row was
  // originally curated for (hub_home_pick_*, kids_home_pick_*). A site reusing
  // the row keeps the Worker's domain prefix but reports revenue under another
  // site's placement name — measured on laplandgifts 2026-08-14, where GYG
  // income could not be attributed to any gifts page. Callers that reuse
  // another site's picks MUST pass their own sid; single-site callers omit it.
  const p = new URLSearchParams({ sid: sidOverride || pick.sid });
  // GYG's own language codes; en is their default and needs no parameter.
  const L: Record<string, string> = {
    fi: "fi", de: "de", ja: "ja", es: "es", "pt-BR": "pt-br",
    "zh-CN": "zh", ko: "ko", fr: "fr", it: "it", nl: "nl", sv: "sv",
  };
  const code = lang ? L[lang] : undefined;
  if (code) p.set("language", code);
  return `${GO}/${pick.path}?${p.toString()}`;
}

