// ─────────────────────────────────────────────────────────────────────────────
// Category links, not product cards.
//
// These four sites do NOT get a "book this exact thing" showcase, because the
// GetYourGuide supply does not honestly match what the site promises. Measured
// 2026-07-30 against the 839-product catalogue:
//
//   skiresorts  ski-snowboard has 56 results, but the top-ranked ones are ice
//               karting and husky sledding. A ski-resort page headlining a husky
//               ride is a mismatch the visitor notices.
//   dining      food-drinks has 312 results, yet they are overwhelmingly
//               snowmobile-safari-with-lunch and aurora-tour-with-BBQ. Food is
//               the side dish, not the product.
//   food        same pool, same problem.
//   transport   transfers + airport-transfers total 54 across 5 destinations,
//               and several are sightseeing tours wearing the word "transfer".
//
// 🔴 nightlife-bars-tc109 has TWO results in the entire region, so laplandbars
// and laplandnightlife get nothing here at all. Forcing four cards would mean
// inventing relevance, which is the same defect as a fabricated statistic.
//
// A category link stays honest and never goes stale: GetYourGuide maintains the
// list, so it cannot rot the way a hardcoded product id does.
// ─────────────────────────────────────────────────────────────────────────────

export interface GygCategoryLink {
  /** `<location-lNNN>/<name-tcNNN>` — verified live. */
  path: string;
  /** Live result count when verified. Documentation only, never rendered. */
  results: number;
  sid: string;
}

